1	// The constructor keeps a public named param (`remoteDataSource`) distinct
2	// from the private field it initializes, matching `vault_repository_impl.
3	// dart`'s documented convention.
4	// ignore_for_file: prefer_initializing_formals
5	import 'dart:async';
6	
7	import 'package:fpdart/fpdart.dart';
8	
9	import '../../../../core/failure/failure.dart';
10	import '../../domain/repositories/account_settings_repository.dart';
11	import '../datasources/account_remote_data_source.dart';
12	
13	/// Owns the one broadcast `biometricEnabled` stream Story 2.4's AD-14-style
14	/// seam requires. Covers the I/O & Edge-Case Matrix exactly:
15	/// - boot fetch resolves `false`/`true` -> [currentBiometricEnabled]/
16	///   [biometricEnabledStream] updated to that value.
17	/// - boot fetch fails -> swallowed, [currentBiometricEnabled] unchanged.
18	/// - [setBiometricEnabled] -> flips immediately (optimistic), PATCH fires;
19	///   success leaves it flipped, failure reverts it and returns `Left`.
20	class AccountSettingsRepositoryImpl implements AccountSettingsRepository {
21	  AccountSettingsRepositoryImpl({
22	    required AccountRemoteDataSource remoteDataSource,
23	  }) : _remoteDataSource = remoteDataSource;
24	
25	  final AccountRemoteDataSource _remoteDataSource;
26	  final StreamController<bool> _controller = StreamController<bool>.broadcast();
27	
28	  /// Starts `true` (never `null`, Boundaries) — the single source of truth
29	  /// for both the vault gate and the Configurações toggle.
30	  bool _currentValue = true;
31	
32	  @override
33	  bool get currentBiometricEnabled => _currentValue;
34	
35	  @override
36	  Stream<bool> get biometricEnabledStream {
37	    // Same `Stream.multi` replay-to-late-listeners rationale as
38	    // `VaultRepositoryImpl.statusStream`/`SessionRepositoryImpl.
39	    // statusStream`: a listener that subscribes after construction still
40	    // immediately sees the cached current value rather than nothing until
41	    // the next emission.
42	    return Stream<bool>.multi((controller) {
43	      controller.add(_currentValue);
44	      final subscription = _controller.stream.listen(
45	        controller.add,
46	        onError: controller.addError,
47	        onDone: controller.close,
48	      );
49	      controller.onCancel = subscription.cancel;
50	    }, isBroadcast: true);
51	  }
52	
53	  void _emit(bool value) {
54	    // Guards against `dispose()` (wired to `get_it`'s `sl.reset()`) racing
55	    // an in-flight `fetchBiometricEnabled()`/`setBiometricEnabled()` call —
56	    // mirrors `VaultRepositoryImpl._emit`'s own guard.
57	    if (_controller.isClosed) {
58	      return;
59	    }
60	    _currentValue = value;
61	    _controller.add(value);
62	  }
63	
64	  @override
65	  Future<Either<Failure, Unit>> fetchBiometricEnabled() async {
66	    final result = await _remoteDataSource.fetchSettings();
67	    return result.match((failure) {
68	      // Swallowed, fire-and-forget like `SessionRepository.
69	      // restoreSession()` — `currentBiometricEnabled` stays exactly as it
70	      // was (I/O matrix: "Boot fetch fails").
71	      return left(failure);
72	    }, (dto) {
73	      _emit(dto.biometricEnabled);
74	      return right(unit);
75	    });
76	  }
77	
78	  @override
79	  Future<Either<Failure, Unit>> setBiometricEnabled(bool enabled) async {
80	    final previous = _currentValue;
81	    // Optimistic flip — switches immediately, before the PATCH call below
82	    // even starts (RNF01, <100ms; Boundaries).
83	    _emit(enabled);
84	    final result = await _remoteDataSource.updateBiometricEnabled(enabled);
85	    return result.match((failure) {
86	      // Revert on failure — the caller surfaces `failure.message` inline.
87	      _emit(previous);
88	      return left(failure);
89	    }, (_) => right(unit));
90	  }
91	
92	  @override
93	  Future<void> dispose() async {
94	    await _controller.close();
95	  }
96	}
