3	import 'package:flutter/material.dart';
4	import 'package:fpdart/fpdart.dart' hide State;
5	import 'package:go_router/go_router.dart';
6	
7	import 'core/di/injection_container.dart';
8	import 'core/failure/failure.dart';
9	import 'core/navigation/app_router.dart';
10	import 'core/navigation/expiry_overlay_host.dart';
11	import 'features/account/domain/repositories/account_settings_repository.dart';
12	import 'features/auth/domain/repositories/session_repository.dart';
13	import 'features/vault/domain/repositories/vault_repository.dart';
14	
15	Future<void> main() async {
16	  WidgetsFlutterBinding.ensureInitialized();
17	  try {
18	    await setupCoreDependencies();
19	  } catch (error) {
20	    debugPrint(
21	      'Cerne failed to start: could not load .env ($error). Copy '
22	      '.env.example to .env and fill in FUNCTIONS_BASE_URL + '
23	      'SUPABASE_ANON_KEY before running the app.',
24	    );
25	    rethrow;
26	  }
27	  runApp(const CerneApp());
28	}
29	
30	/// Root widget. Portrait-only, light-mode-only, fixed 390x844 frame — no
31	/// breakpoint, landscape or dark-mode path anywhere in the app (per the
32	/// epic's UX constraints; the portrait lock itself lives in
33	/// `ios/Runner/Info.plist`, Story 1.6).
34	///
35	/// Story 1.6 scope: the ad-hoc `StreamBuilder`/`Navigator.push` shell
36	/// Stories 1.3-1.5 built this on top of is replaced by the one real
37	/// `go_router` (`core/navigation/app_router.dart`) plus its
38	/// `ExpiryOverlayHost` wrapper — [restoreSession] still fires once at boot
39	/// here (unchanged from Story 1.4), but every screen transition and the
40	/// expiry overlay's own "Entrar novamente" now go through that router
41	/// instead of an imperative `Navigator`.
42	class CerneApp extends StatefulWidget {
43	  const CerneApp({super.key});
44	
45	  @override
46	  State<CerneApp> createState() => _CerneAppState();
47	}
48	
49	class _CerneAppState extends State<CerneApp> {
50	  late final SessionRepository _sessionRepository;
51	  late final VaultRepository _vaultRepository;
52	  late final AccountSettingsRepository _accountSettingsRepository;
53	  late final GoRouter _router;
54	
55	  // Created here (not left for `GoRouter` to generate internally) and
56	  // passed to both `buildAppRouter` and `ExpiryOverlayHost` below, so the
57	  // latter can reach the Navigator's own `BuildContext` through this
58	  // public, documented key instead of reaching into `GoRouter`'s internal
59	  // `routerDelegate`.
60	  final GlobalKey<NavigatorState> _navigatorKey = GlobalKey<NavigatorState>(
61	    debugLabel: 'root',
62	  );
63	
64	  @override
65	  void initState() {
66	    super.initState();
67	    _sessionRepository = sl<SessionRepository>();
68	    _vaultRepository = sl<VaultRepository>();
69	    _accountSettingsRepository = sl<AccountSettingsRepository>();
70	    _router = buildAppRouter(
71	      vaultRepository: _vaultRepository,
72	      sessionRepository: _sessionRepository,
73	      accountSettingsRepository: _accountSettingsRepository,
74	      navigatorKey: _navigatorKey,
75	    );
76	    // Fire-and-forget: the outcome reaches the UI through
77	    // `SessionRepository.currentStatus`/`statusStream` (which the router's
78	    // `redirect`/`refreshListenable` already watch), not through this
79	    // call's return value. `restoreSession()` already maps every internal
80	    // failure to `Left`/an `unauthenticated` emission and never throws.
81	    // This `catchError` is NOT a UI recovery path — its handler's return
82	    // value is discarded by `unawaited` and never reaches `statusStream`.
83	    // It exists purely so a future regression that broke the "never
84	    // throws" contract above would surface as a logged message instead of
85	    // an unhandled zone exception.
86	    unawaited(
87	      _sessionRepository.restoreSession().catchError(_asUnauthenticated),
88	    );
89	    // Story 2.4 — boot-time read of `biometricEnabled`, same
90	    // fire-and-forget rationale as `restoreSession()` above: the outcome
91	    // reaches `VaultLockScreen` through `AccountSettingsRepository.
92	    // currentBiometricEnabled`/`biometricEnabledStream` (which the router's
93	    // `refreshListenable` already watches), never through this call's
94	    // return value, and a failure leaves `currentBiometricEnabled`
95	    // unchanged (I/O matrix) rather than surfacing anywhere.
96	    unawaited(
97	      _accountSettingsRepository.fetchBiometricEnabled().catchError(
98	        _asUnchangedPreference,
99	      ),
100	    );
101	  }
102	
103	  @override
104	  void dispose() {
105	    _router.dispose();
106	    super.dispose();
107	  }
108	
109	  // `catchError`'s handler must still complete the Future with a value of
110	  // its declared type (`Either<Failure, Unit>`) — a `void`-returning
111	  // handler would try to complete it with `null`, which isn't assignable
112	  // to that non-nullable type and would itself throw.
113	  static Either<Failure, Unit> _asUnauthenticated(
114	    Object error,
115	    StackTrace stackTrace,
116	  ) {
117	    debugPrint('CerneApp: restoreSession() threw unexpectedly ($error)');
118	    return left(Failure.malformedResponse(message: error.toString()));
119	  }
120	
121	  // Same rationale as `_asUnauthenticated` above, for
122	  // `fetchBiometricEnabled()`'s own "never throws" contract.
123	  static Either<Failure, Unit> _asUnchangedPreference(
124	    Object error,
125	    StackTrace stackTrace,
126	  ) {
127	    debugPrint(
128	      'CerneApp: fetchBiometricEnabled() threw unexpectedly ($error)',
129	    );
130	    return left(Failure.malformedResponse(message: error.toString()));
131	  }
132	
133	  @override
134	  Widget build(BuildContext context) {
135	    return MaterialApp.router(
136	      debugShowCheckedModeBanner: false,
137	      routerConfig: _router,
138	      builder: (context, child) => ExpiryOverlayHost(
139	        sessionRepository: _sessionRepository,
140	        router: _router,
141	        navigatorKey: _navigatorKey,
142	        child: child!,
143	      ),
144	    );
145	  }
146	}
