12	/// `setBiometricEnabled()` result plus a real stream the cubit actually
13	/// subscribes to, which a mocktail stub can't give as naturally.
14	class _FakeAccountSettingsRepository implements AccountSettingsRepository {
15	  bool _value = true;
16	  final _controller = StreamController<bool>.broadcast();
17	
18	  /// The next `setBiometricEnabled()` call's own result — defaults to a
19	  /// failure so a test must opt in to the success path explicitly.
20	  Either<Failure, Unit> setBiometricEnabledResult = left(
21	    const Failure.malformedResponse(message: 'fake: not configured'),
22	  );
23	
24	  int setBiometricEnabledCallCount = 0;
25	
26	  @override
27	  bool get currentBiometricEnabled => _value;
28	
29	  @override
30	  Stream<bool> get biometricEnabledStream {
31	    return Stream<bool>.multi((controller) {
32	      controller.add(_value);
33	      final subscription = _controller.stream.listen(
34	        controller.add,
35	        onError: controller.addError,
36	        onDone: controller.close,
37	      );
38	      controller.onCancel = subscription.cancel;
39	    }, isBroadcast: true);
40	  }
41	
42	  @override
43	  Future<Either<Failure, Unit>> fetchBiometricEnabled() async =>
44	      right(unit);
45	
46	  @override
47	  Future<Either<Failure, Unit>> setBiometricEnabled(bool enabled) async {
48	    setBiometricEnabledCallCount += 1;
49	    final previous = _value;
50	    _emit(enabled);
51	    final result = setBiometricEnabledResult;
52	    if (result.isLeft()) {
53	      _emit(previous);
54	    }
55	    return result;
56	  }
57	
58	  @override
59	  Future<void> dispose() => _controller.close();
60	
61	  void _emit(bool value) {
62	    _value = value;
63	    _controller.add(value);
64	  }
65	}
66	
67	Future<List<AccountSettingsState>> _emittedDuring(
68	  AccountSettingsCubit cubit,
69	  Future<void> Function() act,
70	) async {
71	  final emitted = <AccountSettingsState>[];
72	  final subscription = cubit.stream.listen(emitted.add);
73	  await act();
74	  await Future<void>.delayed(Duration.zero);
75	  await subscription.cancel();
76	  return emitted;
77	}
78	
79	void main() {
80	  late _FakeAccountSettingsRepository fakeRepository;
81	
82	  setUp(() {
83	    fakeRepository = _FakeAccountSettingsRepository();
84	  });
85	
86	  group('initial state', () {
87	    test('mirrors currentBiometricEnabled (true) at construction', () async {
88	      final cubit = AccountSettingsCubit(fakeRepository);
89	
90	      expect(cubit.state.biometricEnabled, isTrue);
91	      expect(cubit.state.errorMessage, isNull);
92	      await cubit.close();
93	    });
94	
95	    test('mirrors a false currentBiometricEnabled (e.g. already fetched '
96	        'before the screen opened)', () async {
97	      fakeRepository._emit(false);
98	      final cubit = AccountSettingsCubit(fakeRepository);
99	
100	      expect(cubit.state.biometricEnabled, isFalse);
101	      await cubit.close();
102	    });
103	  });
104	
105	  group('toggleBiometric() — success', () {
106	    test('flips to the new value and clears any prior error, calling the '
107	        'repository with exactly the requested value', () async {
108	      fakeRepository.setBiometricEnabledResult = right(unit);
109	      final cubit = AccountSettingsCubit(fakeRepository);
110	
111	      final emitted = await _emittedDuring(
112	        cubit,
113	        () => cubit.toggleBiometric(false),
114	      );
115	
116	      expect(emitted.last.biometricEnabled, isFalse);
117	      expect(emitted.last.errorMessage, isNull);
118	      expect(fakeRepository.setBiometricEnabledCallCount, 1);
119	      await cubit.close();
120	    });
121	  });
122	
123	  group('toggleBiometric() — failure', () {
124	    test('the switch reverts (mirrored from the repository\'s own revert) '
125	        'and the Failure\'s message is surfaced', () async {
126	      fakeRepository.setBiometricEnabledResult = left(
127	        const Failure.networkTimeout(message: 'Sem conexão'),
128	      );
129	      final cubit = AccountSettingsCubit(fakeRepository);
130	
131	      final emitted = await _emittedDuring(
132	        cubit,
133	        () => cubit.toggleBiometric(false),
134	      );
135	
136	      // Mirrors the repository's own emit sequence: optimistic flip to
137	      // false, then reverted back to true, plus the error message set by
138	      // toggleBiometric()'s own failure branch.
139	      expect(emitted.map((s) => s.biometricEnabled), [false, true, true]);
140	      expect(cubit.state.biometricEnabled, isTrue);
141	      expect(cubit.state.errorMessage, 'Sem conexão');
142	      await cubit.close();
143	    });
144	
145	    test('a later successful toggle clears the previous error message',
146	        () async {
147	      fakeRepository.setBiometricEnabledResult = left(
148	        const Failure.networkTimeout(message: 'Sem conexão'),
149	      );
150	      final cubit = AccountSettingsCubit(fakeRepository);
151	      await cubit.toggleBiometric(false);
152	      expect(cubit.state.errorMessage, 'Sem conexão');
153	
154	      fakeRepository.setBiometricEnabledResult = right(unit);
155	      await cubit.toggleBiometric(true);
156	
157	      expect(cubit.state.errorMessage, isNull);
158	      expect(cubit.state.biometricEnabled, isTrue);
159	      await cubit.close();
160	    });
161	  });
162	}
