504	    // test in this file. These mock `SystemChannels.accessibility`
505	    // directly — the channel `SemanticsService.sendAnnouncement` sends
506	    // on — to assert the real announcement content.
507	    List<String> interceptAnnouncements(WidgetTester tester) {
508	      final messages = <String>[];
509	      tester.binding.defaultBinaryMessenger.setMockDecodedMessageHandler<
510	        dynamic
511	      >(SystemChannels.accessibility, (dynamic call) async {
