  expect(emitted.last.biometricEnabled, isTrue);
  expect(emitted.last.errorMessage, 'Sem conexão');
  expect(cubit.state.biometricEnabled, isTrue);
  expect(cubit.state.errorMessage, 'Sem conexão');
  await cubit.close();
});

