14	/// Same plain (non-mocktail) fake shape as
15	/// `account_settings_cubit_test.dart`'s own `_FakeAccountSettingsRepository`
16	/// — this suite needs a scriptable `setBiometricEnabled()` result plus a
17	/// real stream the cubit (built from this fake, not mocked) actually
18	/// subscribes to.
19	class _FakeAccountSettingsRepository implements AccountSettingsRepository {
20	  bool _value = true;
21	  final _controller = StreamController<bool>.broadcast();
22	
23	  /// The next `setBiometricEnabled()` call's own result — defaults to a
24	  /// failure so a test must opt in to the success path explicitly, same
25	  /// convention as the cubit-level fake.
26	  Either<Failure, Unit> setBiometricEnabledResult = left(
27	    const Failure.malformedResponse(message: 'fake: not configured'),
28	  );
29	
30	  @override
31	  bool get currentBiometricEnabled => _value;
32	
33	  @override
34	  Stream<bool> get biometricEnabledStream {
35	    return Stream<bool>.multi((controller) {
36	      controller.add(_value);
37	      final subscription = _controller.stream.listen(
38	        controller.add,
39	        onError: controller.addError,
40	        onDone: controller.close,
41	      );
42	      controller.onCancel = subscription.cancel;
43	    }, isBroadcast: true);
44	  }
45	
46	  @override
47	  Future<Either<Failure, Unit>> fetchBiometricEnabled() async => right(unit);
48	
49	  @override
50	  Future<Either<Failure, Unit>> setBiometricEnabled(bool enabled) async {
51	    final previous = _value;
52	    _emit(enabled);
53	    final result = setBiometricEnabledResult;
54	    if (result.isLeft()) {
55	      _emit(previous);
56	    }
57	    return result;
58	  }
59	
60	  @override
61	  Future<void> dispose() => _controller.close();
62	
63	  void _emit(bool value) {
64	    _value = value;
65	    _controller.add(value);
66	  }
67	}
68	
69	/// `/configuracoes`'s `BackArrowHeader` does `context.go('/')`
70	/// (`back_arrow_header_test.dart`'s own rationale) — needs a real
71	/// `GoRouter` ancestor to resolve, hence this minimal two-route wrapper
72	/// rather than a bare `MaterialApp`.
73	GoRouter _routerWith(Widget screen) {
74	  return GoRouter(
75	    initialLocation: '/configuracoes',
76	    routes: [
77	      GoRoute(path: '/', builder: (context, state) => const Text('Home')),
78	      GoRoute(path: '/configuracoes', builder: (context, state) => screen),
79	    ],
80	  );
81	}
82	
83	/// Proves spec-2-4's Acceptance Criteria directly against the real screen
84	/// widget: "shows only the biometric toggle" (minimal), the toggle mirrors
85	/// the cubit's state, tapping it drives `toggleBiometric()`, and a failed
86	/// toggle's error message renders inline — `app_router_test.dart` already
87	/// proves the screen is *reachable*; this suite proves its own rendering
88	/// and interaction in isolation.
89	void main() {
90	  late _FakeAccountSettingsRepository fakeRepository;
91	  late AccountSettingsCubit cubit;
92	
93	  setUp(() {
94	    fakeRepository = _FakeAccountSettingsRepository();
95	    cubit = AccountSettingsCubit(fakeRepository);
96	  });
97	
98	  tearDown(() async {
99	    await cubit.close();
100	    await fakeRepository.dispose();
101	  });
102	
103	  Future<void> pump(WidgetTester tester) async {
104	    final router = _routerWith(AccountSettingsScreen(cubit: cubit));
105	    addTearDown(router.dispose);
106	    await tester.pumpWidget(MaterialApp.router(routerConfig: router));
107	  }
108	
109	  testWidgets(
110	    'shows the header titled Configurações and exactly one switch — no '
111	    'other content (AC: "shows only the biometric toggle")',
112	    (tester) async {
113	      await pump(tester);
114	
115	      expect(find.byType(BackArrowHeader), findsOneWidget);
116	      expect(find.text('Configurações'), findsOneWidget);
117	      expect(find.byType(Switch), findsOneWidget);
118	      expect(find.text('Entrar com biometria'), findsOneWidget);
119	    },
120	  );
121	
122	  testWidgets(
123	    'the switch mirrors currentBiometricEnabled (true) at construction',
124	    (tester) async {
125	      await pump(tester);
126	
127	      final switchWidget = tester.widget<Switch>(find.byType(Switch));
128	      expect(switchWidget.value, isTrue);
129	    },
130	  );
131	
132	  testWidgets(
133	    'a false currentBiometricEnabled (already fetched before the screen '
134	    'opened) renders the switch off',
135	    (tester) async {
136	      fakeRepository._emit(false);
137	      cubit = AccountSettingsCubit(fakeRepository);
138	
139	      await pump(tester);
140	
141	      final switchWidget = tester.widget<Switch>(find.byType(Switch));
142	      expect(switchWidget.value, isFalse);
143	    },
144	  );
145	
146	  testWidgets(
147	    'tapping the switch calls toggleBiometric() with the requested value and '
148	    'flips the rendered switch — no error band on success',
149	    (tester) async {
150	      fakeRepository.setBiometricEnabledResult = right(unit);
151	      await pump(tester);
152	
153	      await tester.tap(find.byType(Switch));
154	      // The `biometricEnabled` mirror travels repository -> Stream.multi's
155	      // own forwarding subscription -> cubit's `emit()` -> BlocBuilder's
156	      // rebuild, several microtask hops deep (same rationale as
157	      // `account_settings_cubit_test.dart`'s own `pumpEventQueue()` use) —
158	      // `pumpAndSettle()` alone only pumps while a frame is scheduled,
159	      // which doesn't guarantee every one of those hops has already run by
160	      // the time it quiesces, so the microtask queue is drained explicitly
161	      // first.
162	      await pumpEventQueue();
163	      await tester.pumpAndSettle();
164	
165	      final switchWidget = tester.widget<Switch>(find.byType(Switch));
166	      expect(switchWidget.value, isFalse);
167	      expect(find.byType(Text), isNot(findsNWidgets(0)));
168	      // No error text rendered — only the label and the back-arrow title.
169	      expect(find.textContaining('conexão'), findsNothing);
170	    },
171	  );
172	
173	  testWidgets(
174	    'a failed toggle reverts the switch and shows the Failure\'s message '
175	    'inline, below the toggle row',
176	    (tester) async {
177	      fakeRepository.setBiometricEnabledResult = left(
178	        const Failure.networkTimeout(message: 'Sem conexão'),
179	      );
180	      await pump(tester);
181	
182	      await tester.tap(find.byType(Switch));
183	      // Same rationale as the success test above — drains the
184	      // stream-mirrored `biometricEnabled` update's own microtask hops
185	      // before asserting on the settled widget tree.
186	      await pumpEventQueue();
187	      await tester.pumpAndSettle();
188	
189	      final switchWidget = tester.widget<Switch>(find.byType(Switch));
190	      expect(switchWidget.value, isTrue);
191	      expect(find.text('Sem conexão'), findsOneWidget);
192	    },
193	  );
194	
195	  testWidgets(
196	    'the back arrow navigates to / (shared BackArrowHeader behavior)',
197	    (tester) async {
198	      await pump(tester);
199	
200	      await tester.tap(find.byIcon(Icons.chevron_left));
201	      await tester.pumpAndSettle();
202	
203	      expect(find.text('Home'), findsOneWidget);
204	    },
205	  );
206	}
