class CounterRepo {
  final _controller = StreamController<int>.broadcast();
  int _value = 0;
  int get current => _value;
  Stream<int> get stream => _controller.stream;
  Future<void> setValue(int v) async {
    _value = v;
    _controller.add(v);
  }
  Future<void> dispose() => _controller.close();
}

class CounterCubit extends Cubit<int> {
  CounterCubit(this._repo) : super(_repo.current) {
    _sub = _repo.stream.listen((value) => emit(value));
  }
  final CounterRepo _repo;
  late final StreamSubscription<int> _sub;

  Future<void> bump(int v) async {
    await _repo.setValue(v);
  }

  @override
  Future<void> close() async {
    await _sub.cancel();
    return super.close();
  }
}

