7	/// Drives [AccountSettingsScreen]: just the one toggle's current value
8	/// (mirrored straight from [AccountSettingsRepository.biometricEnabledStream]
9	/// — the repository is the single source of truth, Boundaries) plus an
10	/// inline error message for a failed toggle.
11	class AccountSettingsState {
12	  const AccountSettingsState({
13	    required this.biometricEnabled,
14	    this.errorMessage,
15	  });
16	
17	  final bool biometricEnabled;
18	
19	  /// Set only once [AccountSettingsCubit.toggleBiometric]'s own PATCH call
20	  /// fails — the switch itself has already reverted via the repository's
21	  /// own stream by the time this is shown (I/O matrix: "Toggle fails ->
22	  /// switch reverts ... Failure.message shown inline").
23	  final String? errorMessage;
24	
25	  AccountSettingsState copyWith({
26	    bool? biometricEnabled,
27	    String? errorMessage,
28	    bool clearErrorMessage = false,
29	  }) {
30	    return AccountSettingsState(
31	      biometricEnabled: biometricEnabled ?? this.biometricEnabled,
32	      errorMessage: clearErrorMessage
33	          ? null
34	          : (errorMessage ?? this.errorMessage),
35	    );
36	  }
37	
38	  @override
39	  bool operator ==(Object other) =>
40	      identical(this, other) ||
41	      (other is AccountSettingsState &&
42	          other.biometricEnabled == biometricEnabled &&
43	          other.errorMessage == errorMessage);
44	
45	  @override
46	  int get hashCode => Object.hash(biometricEnabled, errorMessage);
47	
48	  @override
49	  String toString() =>
50	      'AccountSettingsState(biometricEnabled: $biometricEnabled, '
51	      'errorMessage: $errorMessage)';
52	}
53	
54	/// Calls [AccountSettingsRepository] directly (no use-case — same small-
55	/// scope rationale `AuthCubit`'s own doc gives). [toggleBiometric] is the
56	/// I/O matrix's optimistic flip/revert, end to end: the repository itself
57	/// flips [AccountSettingsRepository.currentBiometricEnabled] immediately
58	/// and emits it on [AccountSettingsRepository.biometricEnabledStream] —
59	/// this cubit only mirrors that stream into its own [AccountSettingsState]
60	/// (subscribed once, at construction) and separately layers the
61	/// toggle-failure error message on top.
62	class AccountSettingsCubit extends Cubit<AccountSettingsState> {
63	  AccountSettingsCubit(this._repository)
64	    : super(
65	        AccountSettingsState(
66	          biometricEnabled: _repository.currentBiometricEnabled,
67	        ),
68	      ) {
69	    _subscription = _repository.biometricEnabledStream.listen(
70	      (value) => emit(state.copyWith(biometricEnabled: value)),
71	    );
72	  }
73	
74	  final AccountSettingsRepository _repository;
75	  late final StreamSubscription<bool> _subscription;
76	
77	  Future<void> toggleBiometric(bool value) async {
78	    emit(state.copyWith(clearErrorMessage: true));
79	    final result = await _repository.setBiometricEnabled(value);
80	    result.match(
81	      (failure) => emit(state.copyWith(errorMessage: failure.message)),
82	      (_) {},
83	    );
84	  }
85	
86	  @override
87	  Future<void> close() async {
88	    await _subscription.cancel();
89	    return super.close();
90	  }
91	}
