14	/// Same plain (non-mocktail) fake shape as
15	/// `account_settings_cubit_test.dart`'s own `_FakeAccountSettingsRepository`
16	/// — this suite needs a scriptable `setBiometricEnabled()` result plus a
17	/// real stream the cubit (built from this fake, not mocked) actually
18	/// subscribes to.
19	class _FakeAccountSettingsRepository implements AccountSettingsRepository {
20	  bool _value = true;
21	  final _controller = StreamController<bool>.broadcast();
22	
23	  /// The next `setBiometricEnabled()` call's own result — defaults to a
24	  /// failure so a test must opt in to the success path explicitly, same
25	  /// convention as the cubit-level fake.
26	  Either<Failure, Unit> setBiometricEnabledResult = left(
27	    const Failure.malformedResponse(message: 'fake: not configured'),
28	  );
29	
30	  @override
31	  bool get currentBiometricEnabled => _value;
32	
33	  @override
34	  Stream<bool> get biometricEnabledStream => _controller.stream;
35	
36	  @override
37	  Future<Either<Failure, Unit>> fetchBiometricEnabled() async => right(unit);
38	
39	  @override
40	  Future<Either<Failure, Unit>> setBiometricEnabled(bool enabled) async {
41	    final previous = _value;
42	    _emit(enabled);
43	    final result = setBiometricEnabledResult;
44	    if (result.isLeft()) {
45	      _emit(previous);
46	    }
47	    return result;
48	  }
49	
50	  @override
51	  Future<void> dispose() => _controller.close();
52	
53	  void _emit(bool value) {
54	    _value = value;
55	    _controller.add(value);
56	  }
57	}
58	
59	/// Drains the `biometricEnabled` mirror's own round trip (repository ->
60	/// `Stream.multi`'s forwarding subscription -> cubit's `emit()` ->
61	/// `BlocBuilder`'s rebuild, several microtask hops deep) with a handful of
62	/// plain `tester.pump()` calls — NOT `pumpEventQueue()`, which schedules its
63	/// own recursive zero-duration `Timer`s and, empirically, never resolves
64	/// inside this widget-test binding (observed hang); `pumpAndSettle()` alone
65	/// doesn't help either, since it only keeps pumping while a *frame* is
66	/// already scheduled, which the first hop hasn't triggered yet.
67	Future<void> _drainStreamMirror(WidgetTester tester) async {
68	  for (var i = 0; i < 20; i++) {
69	    await tester.pump();
70	  }
71	}
72	
73	/// `/configuracoes`'s `BackArrowHeader` does `context.go('/')`
74	/// (`back_arrow_header_test.dart`'s own rationale) — needs a real
75	/// `GoRouter` ancestor to resolve, hence this minimal two-route wrapper
76	/// rather than a bare `MaterialApp`.
77	GoRouter _routerWith(Widget screen) {
78	  return GoRouter(
79	    initialLocation: '/configuracoes',
80	    routes: [
81	      GoRoute(path: '/', builder: (context, state) => const Text('Home')),
82	      GoRoute(path: '/configuracoes', builder: (context, state) => screen),
83	    ],
84	  );
85	}
