88	/// widget: "shows only the biometric toggle" (minimal), the toggle mirrors
89	/// the cubit's state, tapping it drives `toggleBiometric()`, and a failed
90	/// toggle's error message renders inline — `app_router_test.dart` already
91	/// proves the screen is *reachable*; this suite proves its own rendering
92	/// and interaction in isolation.
93	void main() {
94	  late _FakeAccountSettingsRepository fakeRepository;
95	  late AccountSettingsCubit cubit;
96	
97	  setUp(() {
98	    fakeRepository = _FakeAccountSettingsRepository();
99	    cubit = AccountSettingsCubit(fakeRepository);
100	  });
101	
102	  tearDown(() async {
103	    await cubit.close();
104	    await fakeRepository.dispose();
105	  });
106	
107	  Future<void> pump(WidgetTester tester) async {
108	    final router = _routerWith(AccountSettingsScreen(cubit: cubit));
109	    addTearDown(router.dispose);
110	    await tester.pumpWidget(MaterialApp.router(routerConfig: router));
111	  }
112	
113	  testWidgets(
114	    'shows the header titled Configurações and exactly one switch — no '
115	    'other content (AC: "shows only the biometric toggle")',
116	    (tester) async {
117	      await pump(tester);
118	
119	      expect(find.byType(BackArrowHeader), findsOneWidget);
120	      expect(find.text('Configurações'), findsOneWidget);
121	      expect(find.byType(Switch), findsOneWidget);
122	      expect(find.text('Entrar com biometria'), findsOneWidget);
123	    },
124	  );
125	
126	  testWidgets(
127	    'the switch mirrors currentBiometricEnabled (true) at construction',
128	    (tester) async {
129	      await pump(tester);
