    await cubit.close();
    await fakeRepository.dispose();
  });

  Future<void> pump(WidgetTester tester) async {
    await tester.pumpWidget(MaterialApp(home: AccountSettingsScreen(cubit: cubit)));
  }

  testWidgets('bisect: tap flips switch', (tester) async {
    fakeRepository.setBiometricEnabledResult = right(unit);
