75	  // `biometricEnabled` mirror travels repository -> Stream.multi's own
76	  // forwarding subscription -> cubit's `emit()` -> `_stateController`,
77	  // several microtask hops deep — one `Duration.zero` delay only guarantees
78	  // draining one hop, leaving a later hop's delivery to land after this
79	  // helper already returned.
80	  await pumpEventQueue();
81	  await subscription.cancel();
82	  return emitted;
83	}
