54	/// Calls [AccountSettingsRepository] directly (no use-case — same small-
55	/// scope rationale `AuthCubit`'s own doc gives). [toggleBiometric] is the
56	/// I/O matrix's optimistic flip/revert, end to end: the repository itself
57	/// flips [AccountSettingsRepository.currentBiometricEnabled] immediately
58	/// and emits it on [AccountSettingsRepository.biometricEnabledStream] —
59	/// this cubit only mirrors that stream into its own [AccountSettingsState]
60	/// (subscribed once, at construction) and separately layers the
61	/// toggle-failure error message on top.
62	class AccountSettingsCubit extends Cubit<AccountSettingsState> {
63	  AccountSettingsCubit(this._repository)
64	    : super(
65	        AccountSettingsState(
66	          biometricEnabled: _repository.currentBiometricEnabled,
67	        ),
68	      ) {
