144	  Future<void> _submitPin(String pin) async {
145	    if (_submittingPin) {
146	      return;
147	    }
148	    // Review finding: previously left in place, a stale mismatch/timeout
149	    // message from a prior attempt lingered unchanged through this new
150	    // attempt, with nothing distinguishing "old error, nothing happening"
151	    // from "new attempt in flight" — cleared here so only this attempt's
152	    // own outcome (or the keypad's disabled/dimmed state) is visible.
153	    setState(() {
154	      _submittingPin = true;
155	      _errorMessage = null;
156	    });
157	    try {
158	      final result = await widget.vaultRepository
159	          .submitPin(pin)
160	          .timeout(_submitPinTimeout);
161	      if (!mounted) {
162	        return;
163	      }
164	      if (result.isLeft()) {
165	        // Mismatch: stays locked, no attempt cap — the keypad itself has
166	        // already cleared its own buffer by the time this runs
167	        // (PinKeypad's own contract), so the user can simply try again.
168	        setState(() => _errorMessage = _pinMismatchMessage);
169	        await _announce(_pinMismatchMessage);
170	      }
171	      // On a match (first-use or later), `currentStatus` is already
172	      // `unlocked` and the router navigates away on its own, same as a
173	      // successful `authenticate()`.
