175	      if (!mounted) {
176	        return;
177	      }
178	      // Bounds the wait so a hung secure-storage call can never leave
179	      // `_submittingPin` stuck `true` forever — the `finally` below still
180	      // runs because this `await` has now actually completed (with a
181	      // thrown `TimeoutException`), same retryable outcome as a mismatch.
182	      setState(() => _errorMessage = _submitTimeoutMessage);
183	      await _announce(_submitTimeoutMessage);
184	    } finally {
