26	  TestWidgetsFlutterBinding.ensureInitialized();
27	
28	  const secureStorageChannel = MethodChannel(
29	    'plugins.it_nomads.com/flutter_secure_storage',
30	  );
31	  final fakeNativeStorage = <String, String>{};
32	
33	  Future<dynamic> handleSecureStorageCall(MethodCall call) async {
34	    final args = call.arguments as Map<dynamic, dynamic>;
35	    switch (call.method) {
36	      case 'write':
37	        fakeNativeStorage[args['key'] as String] = args['value'] as String;
38	        return null;
39	      case 'read':
40	        return fakeNativeStorage[args['key'] as String];
41	      case 'delete':
42	        fakeNativeStorage.remove(args['key'] as String);
43	        return null;
44	      case 'containsKey':
45	        return fakeNativeStorage.containsKey(args['key'] as String);
46	      default:
47	        return null;
48	    }
49	  }
