12	class MockAccountRemoteDataSource extends Mock
13	    implements AccountRemoteDataSource {}
14	
15	/// Covers spec-2-4's I/O & Edge-Case Matrix exactly:
16	/// - boot fetch resolves `false`/`true` -> `currentBiometricEnabled`/
17	///   `biometricEnabledStream` updated.
18	/// - boot fetch fails -> swallowed, `currentBiometricEnabled` unchanged.
19	/// - toggle succeeds -> flips immediately, persists, no error.
20	/// - toggle fails -> reverts to the prior value, `Left(Failure)` returned
21	///   so the caller can surface its message.
22	void main() {
23	  late MockAccountRemoteDataSource mockRemoteDataSource;
24	  late AccountSettingsRepositoryImpl repository;
25	
26	  setUp(() {
27	    mockRemoteDataSource = MockAccountRemoteDataSource();
28	    repository = AccountSettingsRepositoryImpl(
29	      remoteDataSource: mockRemoteDataSource,
30	    );
31	  });
32	
33	  tearDown(() => repository.dispose());
34	
35	  /// Same rationale as `vault_repository_impl_test.dart`'s own
36	  /// `emittedDuring` helper: `biometricEnabledStream` always synchronously
37	  /// replays the current value to a brand-new listener, so that replay is
38	  /// drained and discarded here first.
39	  Future<List<bool>> emittedDuring(Future<void> Function() act) async {
40	    final emitted = <bool>[];
41	    final subscription = repository.biometricEnabledStream.listen(
42	      emitted.add,
43	    );
44	    await Future<void>.delayed(Duration.zero);
45	    emitted.clear();
46	    await act();
47	    await Future<void>.delayed(Duration.zero);
48	    await subscription.cancel();
49	    return emitted;
50	  }
51	
52	  group('currentBiometricEnabled — starts true, never null (Boundaries)', () {
53	    test('currentBiometricEnabled is true before any fetch/toggle call', () {
54	      expect(repository.currentBiometricEnabled, isTrue);
55	    });
56	
57	    test('a listener that subscribes before any call still immediately '
58	        'sees true, not nothing until the first emission (Stream.multi '
59	        'replay)', () async {
60	      final value = await repository.biometricEnabledStream.first;
61	
62	      expect(value, isTrue);
63	    });
64	  });
65	
66	  group('fetchBiometricEnabled() — boot fetch', () {
67	    test('resolves false -> currentBiometricEnabled/stream update to false',
68	        () async {
69	      when(() => mockRemoteDataSource.fetchSettings()).thenAnswer(
70	        (_) async => right(const AccountSettingsDto(biometricEnabled: false)),
71	      );
72	
73	      Either<Failure, Unit>? result;
74	      final emitted = await emittedDuring(() async {
75	        result = await repository.fetchBiometricEnabled();
76	      });
77	
78	      expect(emitted, [false]);
79	      expect(repository.currentBiometricEnabled, isFalse);
80	      expect(result!.isRight(), isTrue);
81	    });
82	
83	    test('resolves true -> currentBiometricEnabled/stream update to true '
84	        '(still true, but goes through the real emit path, not just the '
85	        'untouched default)', () async {
86	      when(() => mockRemoteDataSource.fetchSettings()).thenAnswer(
87	        (_) async => right(const AccountSettingsDto(biometricEnabled: true)),
88	      );
89	
90	      Either<Failure, Unit>? result;
91	      final emitted = await emittedDuring(() async {
92	        result = await repository.fetchBiometricEnabled();
93	      });
94	
95	      expect(emitted, [true]);
96	      expect(repository.currentBiometricEnabled, isTrue);
97	      expect(result!.isRight(), isTrue);
98	    });
99	
100	    test('fails -> currentBiometricEnabled unchanged, no emission, '
101	        'Left(Failure) returned (swallowed by the caller, fire-and-forget '
102	        'like restoreSession())', () async {
103	      when(() => mockRemoteDataSource.fetchSettings()).thenAnswer(
104	        (_) async => left(const Failure.networkOffline(message: 'offline')),
105	      );
106	
107	      Either<Failure, Unit>? result;
108	      final emitted = await emittedDuring(() async {
109	        result = await repository.fetchBiometricEnabled();
110	      });
111	
112	      expect(emitted, isEmpty);
113	      expect(repository.currentBiometricEnabled, isTrue);
114	      expect(result!.isLeft(), isTrue);
115	    });
116	  });
117	
118	  group('setBiometricEnabled() — optimistic toggle', () {
119	    test('succeeds -> flips immediately (before the PATCH call resolves) '
120	        'and stays flipped, Right(unit) returned', () async {
121	      final patchCompleter = Completer<Either<Failure, AccountSettingsDto>>();
122	      when(
123	        () => mockRemoteDataSource.updateBiometricEnabled(false),
124	      ).thenAnswer((_) => patchCompleter.future);
125	
126	      final emitted = <bool>[];
127	      final subscription = repository.biometricEnabledStream.listen(
128	        emitted.add,
129	      );
130	      await Future<void>.delayed(Duration.zero);
131	      emitted.clear();
132	
133	      final resultFuture = repository.setBiometricEnabled(false);
134	      // The flip already happened synchronously, before the PATCH call's
135	      // own Future even resolves (RNF01, <100ms — Boundaries).
136	      await Future<void>.delayed(Duration.zero);
137	      expect(repository.currentBiometricEnabled, isFalse);
138	      expect(emitted, [false]);
139	
140	      patchCompleter.complete(
141	        right(const AccountSettingsDto(biometricEnabled: false)),
142	      );
143	      final result = await resultFuture;
144	      await subscription.cancel();
145	
146	      expect(result.isRight(), isTrue);
