/// Lets a test hold `authenticate()` unresolved — same rationale as
/// `vault_lock_screen_test.dart`'s own `authenticateGate`, needed here to
/// observe `/vault` while it's still waiting on the pending attempt
/// (spec-2-4 review finding: a preference change reaching an
/// already-mounted `/vault` while still on the biometric view).
Completer<void>? authenticateGate;

@override
VaultStatus get currentStatus => _status;

@override
Stream<VaultStatus> get statusStream => _controller.stream;

@override
Future<Either<Failure, Unit>> authenticate() async {
  final gate = authenticateGate;
  if (gate != null) {
    await gate.future;
  }
  if (authenticateSucceeds) {
    setStatus(VaultStatus.unlocked);
    return right(unit);
  }
  return left(
    const Failure.malformedResponse(message: 'fake: biometrics declined'),
  );
}

