        // The preference changes while that attempt is still pending —
        // this is exactly the race the finding describes: a boot-time
        // `fetchBiometricEnabled()` (or a toggle elsewhere) resolving to
        // `false` shortly after `/vault` already mounted and already
        // auto-attempted biometric.
        fakeAccountSettingsRepository.setValue(false);
