14	/// Same plain (non-mocktail) fake shape as
15	/// `account_settings_cubit_test.dart`'s own `_FakeAccountSettingsRepository`
16	/// — this suite needs a scriptable `setBiometricEnabled()` result plus a
17	/// real stream the cubit (built from this fake, not mocked) actually
18	/// subscribes to. `biometricEnabledStream` is a plain broadcast stream, not
19	/// a `Stream.multi` replay wrapper (unlike the production repository) —
20	/// `AccountSettingsCubit`'s own constructor already reads
21	/// [currentBiometricEnabled] directly for its initial state, so no replay
22	/// machinery is needed for a fake with exactly one subscriber.
23	class _FakeAccountSettingsRepository implements AccountSettingsRepository {
24	  bool _value = true;
25	  final _controller = StreamController<bool>.broadcast();
26	
27	  /// The next `setBiometricEnabled()` call's own result — defaults to a
28	  /// failure so a test must opt in to the success path explicitly, same
29	  /// convention as the cubit-level fake.
30	  Either<Failure, Unit> setBiometricEnabledResult = left(
31	    const Failure.malformedResponse(message: 'fake: not configured'),
32	  );
33	
34	  @override
35	  bool get currentBiometricEnabled => _value;
36	
37	  @override
38	  Stream<bool> get biometricEnabledStream => _controller.stream;
39	
40	  @override
41	  Future<Either<Failure, Unit>> fetchBiometricEnabled() async => right(unit);
42	
43	  @override
44	  Future<Either<Failure, Unit>> setBiometricEnabled(bool enabled) async {
45	    final previous = _value;
46	    _emit(enabled);
47	    final result = setBiometricEnabledResult;
48	    if (result.isLeft()) {
49	      _emit(previous);
50	    }
51	    return result;
52	  }
53	
54	  @override
55	  Future<void> dispose() => _controller.close();
56	
57	  void _emit(bool value) {
58	    _value = value;
59	    _controller.add(value);
60	  }
61	}
62	
63	/// `/configuracoes`'s `BackArrowHeader` does `context.go('/')`
64	/// (`back_arrow_header_test.dart`'s own rationale) — needs a real
65	/// `GoRouter` ancestor to resolve, hence this minimal two-route wrapper
66	/// rather than a bare `MaterialApp`.
67	GoRouter _routerWith(Widget screen) {
68	  return GoRouter(
69	    initialLocation: '/configuracoes',
70	    routes: [
71	      GoRoute(path: '/', builder: (context, state) => const Text('Home')),
72	      GoRoute(path: '/configuracoes', builder: (context, state) => screen),
73	    ],
74	  );
75	}
76	
77	/// Builds a fresh [_FakeAccountSettingsRepository] + [AccountSettingsCubit]
78	/// pair and pumps the real screen around it, registering both for cleanup.
79	///
80	/// Deliberately constructed *inside* each `testWidgets` body (via this
81	/// helper) rather than in a shared `setUp()` — `setUp()`'s callback runs in
82	/// `package:test`'s own per-test zone, a different zone than the one
83	/// `TestWidgetsFlutterBinding` establishes for the `testWidgets` callback
84	/// itself. A `StreamSubscription` (here, `AccountSettingsCubit`'s own
85	/// subscription to the repository's stream, set up in its constructor)
86	/// created in that outer zone does not reliably get its pending events
87	/// flushed by `tester.pump()`'s zone-scoped microtask draining — observed
88	/// directly: `cubit.state` updated correctly, but the `BlocBuilder`-driven
89	/// widget never rebuilt, no matter how many `pump()` calls followed.
90	/// Constructing the cubit here, inside the same zone `tester.pump()`
91	/// drains, avoids the mismatch entirely.
92	Future<(
93	  _FakeAccountSettingsRepository,
94	  AccountSettingsCubit,
95	)>
96	_pumpScreen(WidgetTester tester) async {
97	  final fakeRepository = _FakeAccountSettingsRepository();
98	  final cubit = AccountSettingsCubit(fakeRepository);
99	  addTearDown(() => cubit.close());
100	  addTearDown(fakeRepository.dispose);
101	
102	  final router = _routerWith(AccountSettingsScreen(cubit: cubit));
103	  addTearDown(router.dispose);
104	  await tester.pumpWidget(MaterialApp.router(routerConfig: router));
105	
106	  return (fakeRepository, cubit);
107	}
108	
109	/// Proves spec-2-4's Acceptance Criteria directly against the real screen
110	/// widget: "shows only the biometric toggle" (minimal), the toggle mirrors
111	/// the cubit's state, tapping it drives `toggleBiometric()`, and a failed
112	/// toggle's error message renders inline — `app_router_test.dart` already
113	/// proves the screen is *reachable*; this suite proves its own rendering
114	/// and interaction in isolation.
115	void main() {
116	  testWidgets(
117	    'shows the header titled Configurações and exactly one switch — no '
118	    'other content (AC: "shows only the biometric toggle")',
119	    (tester) async {
120	      await _pumpScreen(tester);
121	
122	      expect(find.byType(BackArrowHeader), findsOneWidget);
123	      expect(find.text('Configurações'), findsOneWidget);
124	      expect(find.byType(Switch), findsOneWidget);
125	      expect(find.text('Entrar com biometria'), findsOneWidget);
126	    },
127	  );
128	
129	  testWidgets(
130	    'the switch mirrors currentBiometricEnabled (true) at construction',
131	    (tester) async {
132	      await _pumpScreen(tester);
133	
134	      final switchWidget = tester.widget<Switch>(find.byType(Switch));
135	      expect(switchWidget.value, isTrue);
136	    },
137	  );
138	
139	  testWidgets(
140	    'a false currentBiometricEnabled (already fetched before the screen '
141	    'opened) renders the switch off',
142	    (tester) async {
143	      final fakeRepository = _FakeAccountSettingsRepository().._emit(false);
144	      final cubit = AccountSettingsCubit(fakeRepository);
145	      addTearDown(() => cubit.close());
146	      addTearDown(fakeRepository.dispose);
147	
148	      final router = _routerWith(AccountSettingsScreen(cubit: cubit));
149	      addTearDown(router.dispose);
150	      await tester.pumpWidget(MaterialApp.router(routerConfig: router));
151	
152	      final switchWidget = tester.widget<Switch>(find.byType(Switch));
153	      expect(switchWidget.value, isFalse);
154	    },
155	  );
156	
157	  testWidgets(
158	    'tapping the switch calls toggleBiometric() with the requested value and '
159	    'flips the rendered switch — no error band on success',
160	    (tester) async {
161	      final (fakeRepository, _) = await _pumpScreen(tester);
162	      fakeRepository.setBiometricEnabledResult = right(unit);
163	
164	      await tester.tap(find.byType(Switch));
165	      await tester.pumpAndSettle();
166	
167	      final switchWidget = tester.widget<Switch>(find.byType(Switch));
168	      expect(switchWidget.value, isFalse);
169	      // No error text rendered — only the label and the back-arrow title.
170	      expect(find.textContaining('conexão'), findsNothing);
171	    },
172	  );
173	
174	  testWidgets(
175	    'a failed toggle reverts the switch and shows the Failure\'s message '
176	    'inline, below the toggle row',
177	    (tester) async {
178	      final (fakeRepository, _) = await _pumpScreen(tester);
179	      fakeRepository.setBiometricEnabledResult = left(
180	        const Failure.networkTimeout(message: 'Sem conexão'),
181	      );
182	
183	      await tester.tap(find.byType(Switch));
184	      await tester.pumpAndSettle();
185	
186	      final switchWidget = tester.widget<Switch>(find.byType(Switch));
187	      expect(switchWidget.value, isTrue);
188	      expect(find.text('Sem conexão'), findsOneWidget);
189	    },
190	  );
191	
192	  testWidgets(
193	    'the back arrow navigates to / (shared BackArrowHeader behavior)',
194	    (tester) async {
195	      await _pumpScreen(tester);
196	
197	      await tester.tap(find.byIcon(Icons.chevron_left));
198	      await tester.pumpAndSettle();
199	
200	      expect(find.text('Home'), findsOneWidget);
201	    },
202	  );
203	}
